 * Decide, for every task in run order, whether the plan runs it and why.
 * @param {Map<string, {needs: string[], reads: string[], writes: string[]}>} tasks - the parsed tasks.
 * @param {Map<string, string>} recorded - the snapshot's digests.
 * @returns {{name: string, reason: string | undefined}[]} one decision per task, in run order.
 */
export function plan(tasks, recorded) {
  const names = order(tasks)
  const running = new Set()
  const decisions = []

  for (const name of names) {
    const task = tasks.get(name)

    // Combine reads and writes, deduplicate, and sort
    const watched = new Set([...task.reads, ...task.writes])
    const watchedPaths = [...watched].sort()

    // Find the first path reason
    let reason = undefined
    for (const path of watchedPaths) {
      const pathReason = pathReason(path, recorded)
      if (pathReason !== undefined) {
        reason = pathReason
        break
      }
    }

    // If no path reason, check if any dependency runs
    if (reason === undefined) {
      const runningDependencies = task.needs.filter(dep => running.has(dep)).sort()
      if (runningDependencies.length > 0) {
        reason = `needs ${runningDependencies[0]}`
      }
    }

    // Mark as running if it has a reason
    if (reason !== undefined) {
      running.add(name)
    }

    decisions.push({ name, reason })
  }

  return decisions
}"}

